<script setup lang="ts">
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const api=inject<any>('adminFetch')
const types=[{id:'game',label:'Сюжеты'},{id:'article',label:'Статьи'},{id:'reference',label:'Справочник'},{id:'news',label:'Новости'},{id:'novelty',label:'Новинки'}]
const posts=ref<any[]>([]),filter=ref(''),error=ref(''),message=ref(''),pending=ref(false)
const empty=()=>({id:null as number|null,type:'article',slug:'',title:'',excerpt:'',body:'',cover:'',coverAlt:'',category:'',edition:'2014',sources:'',gallery:[] as {url:string;alt:string}[],metaText:'{}',seo_title:'',seo_description:'',published:false})
const form=reactive(empty())
const filtered=computed(()=>posts.value.filter(p=>!filter.value||p.type===filter.value))
async function load(){try{posts.value=await api('/api/admin/posts')}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить материалы'}}
function edit(p:any){Object.assign(form,empty(),p,{cover:p.cover||'',coverAlt:p.meta?.coverAlt||'',category:p.meta?.category||'',edition:p.meta?.edition||'2014',sources:typeof p.meta?.sources==='string'?p.meta.sources:JSON.stringify(p.meta?.sources||[]),gallery:clone(p.meta?.gallery||[]),metaText:JSON.stringify(p.meta||{},null,2)});message.value='';window.scrollTo({top:0,behavior:'smooth'})}
async function save(){pending.value=true;error.value='';message.value='';try{let meta=JSON.parse(form.metaText||'{}');meta={...meta,coverAlt:form.coverAlt,gallery:form.gallery};if(form.type==='reference')meta={...meta,category:form.category,edition:form.edition,sources:form.sources};const body={...form,meta};const result=await api(form.id?`/api/admin/posts/${form.id}`:'/api/admin/posts',{method:form.id?'PUT':'POST',body});edit(result);message.value='Материал сохранён';await load()}catch(e:any){error.value=e?.data?.message||'Проверьте поля и параметры материала'}finally{pending.value=false}}
async function remove(p:any){if(!confirm(`Удалить «${p.title}»? Ссылки на материал перестанут работать.`))return;try{await api(`/api/admin/posts/${p.id}`,{method:'DELETE'});if(form.id===p.id)Object.assign(form,empty());await load()}catch(e:any){error.value=e?.data?.message||'Не удалось удалить материал'}}
onMounted(load)
</script>
<template><section><h2 class="mb-5 text-3xl">Материалы</h2><p v-if="error" role="alert" class="mb-4 text-red-300">{{error}}</p><p v-if="message" role="status" class="mb-4 text-green-300">{{message}}</p><div class="grid items-start gap-6 lg:grid-cols-[1.3fr_1fr]"><form class="card min-w-0 space-y-4" @submit.prevent="save"><div class="flex flex-wrap justify-between gap-2"><h3 class="text-2xl">{{form.id?'Редактирование':'Новый материал'}}</h3><button type="button" class="btn-ghost" @click="Object.assign(form,empty());message=''">Новый</button></div><label class="block">Раздел<select v-model="form.type" class="input mt-1"><option v-for="t in types" :key="t.id" :value="t.id">{{t.label}}</option></select></label><label class="block">Заголовок<input v-model="form.title" class="input mt-1" required maxlength="250"/></label><label class="block">Адрес (slug)<input v-model="form.slug" class="input mt-1" :readonly="!!form.id" placeholder="Автоматически из заголовка"/><span v-if="form.id" class="mt-1 block text-xs text-ash">Адрес сохранён, чтобы существующие ссылки продолжали работать.</span></label><label class="block">Краткое описание<textarea v-model="form.excerpt" class="input mt-1" rows="3" maxlength="2000"/></label><label class="block">Текст<textarea v-model="form.body" class="input mt-1" rows="12" maxlength="100000"/><span class="text-xs text-ash">Абзацы разделяйте пустой строкой. HTML не исполняется.</span></label><template v-if="form.type==='reference'"><label class="block">Категория<input v-model="form.category" class="input mt-1" maxlength="120"/></label><label class="block">Редакция правил<select v-model="form.edition" class="input mt-1"><option>2014</option><option>2024</option><option value="2014 и 2024 — сравнение">2014 и 2024 — сравнение</option><option value="Общие советы">Общие советы</option></select></label><label class="block">Источники<textarea v-model="form.sources" class="input mt-1" rows="4" placeholder="Название источника и URL, по одному на строку"/></label></template><AdminImagePicker v-model="form.cover" label="Обложка"/><label class="block">Описание обложки (alt)<input v-model="form.coverAlt" class="input mt-1" maxlength="300"/></label><details class="rounded border border-white/10 p-3"><summary>Галерея</summary><div v-for="(image,i) in form.gallery" :key="i" class="mt-4 space-y-2 border-t border-white/10 pt-4"><AdminImagePicker v-model="image.url"/><label class="block">Описание фото<input v-model="image.alt" class="input mt-1" maxlength="300"/></label><div class="flex gap-2"><button v-if="i>0" type="button" class="btn-ghost" @click="[form.gallery[i-1],form.gallery[i]]=[form.gallery[i],form.gallery[i-1]]">Выше</button><button type="button" class="btn-ghost" @click="form.gallery.splice(i,1)">Убрать</button></div></div><button type="button" class="btn-ghost mt-3" @click="form.gallery.push({url:'',alt:''})">Добавить фото</button></details><label class="block">SEO title<input v-model="form.seo_title" class="input mt-1" maxlength="250"/></label><label class="block">SEO description<textarea v-model="form.seo_description" class="input mt-1" rows="2" maxlength="1000"/></label><details><summary>Параметры сюжета и дополнительные поля</summary><p class="my-2 text-xs text-ash">Для сюжетов сохраняются system, players, level, kind, genres, duration, adult, series, accent и map. Меняйте значения, сохраняя структуру JSON.</p><textarea v-model="form.metaText" class="input font-mono text-xs" rows="10"/></details><label class="flex min-h-11 items-center gap-2"><input v-model="form.published" type="checkbox"/> Опубликовано (иначе черновик)</label><button class="btn-primary" :disabled="pending">{{pending?'Сохраняем…':'Сохранить'}}</button></form><div class="min-w-0 space-y-3"><label class="block">Показать раздел<select v-model="filter" class="input mt-1"><option value="">Все</option><option v-for="t in types" :key="t.id" :value="t.id">{{t.label}}</option></select></label><div v-for="p in filtered" :key="p.id" class="card"><h3 class="break-words text-2xl">{{p.title}}</h3><p class="my-2 text-xs text-ash">{{types.find(t=>t.id===p.type)?.label}} · {{p.published?'Опубликовано':'Черновик'}}</p><div class="flex flex-wrap gap-2"><button class="btn-ghost" @click="edit(p)">Редактировать</button><button class="btn-ghost" @click="remove(p)">Удалить</button></div></div><p v-if="!filtered.length" class="card text-ash">В этом разделе пока нет материалов.</p></div></div></section></template>
